content.content:
/* Successor design tokens — "cockpit": near-black cabin glass, one BMW-like blue for decisions and focus,
   telltale colours for state. Dark only (PRODUCT.md). */
:root {
  color-scheme: dark;

  /* surfaces */
  --bg: #08090b;
  --bg-glow: rgba(28, 105, 212, 0.07);
  --panel: #0e1014;
  --panel-2: #12151a;
  --hover: #171b22;
  --press: #1c212a;
  --line: #1d2027;
  --line-2: #2a2f39;
  --scrim: rgba(4, 5, 7, 0.72);

  /* text */
  --text: #e8ebf0;
  --text-2: #b9c0cb;
  --muted: #8b94a4;
  --faint: #636c7c;

  /* decision blue */
  --blue: #1c69d4;
  --blue-hi: #4d94ff;
  --blue-ink: #a9cbff;
  --blue-wash: rgba(28, 105, 212, 0.16);
  --blue-line: rgba(77, 148, 255, 0.45);

  /* telltales */
  --amber: #f5a524;
  --amber-ink: #fbd38a;
  --amber-wash: rgba(245, 165, 36, 0.13);
  --red: #ff5a5f;
  --red-ink: #ffb3b5;
  --red-wash: rgba(255, 90, 95, 0.13);
  --green: #3ccf91;
  --green-ink: #a6ecc9;
  --green-wash: rgba(60, 207, 145, 0.13);
  --violet: #a78bfa;
  --violet-wash: rgba(167, 139, 250, 0.14);

  /* type */
  --font: "Mona Sans Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --fs-micro: 11px;
  --fs-small: 12px;
  --fs-body: 14px;
  --fs-lead: 16px;
  --fs-title: 20px;
  --fs-head: 28px;
  --fs-display: 44px;
  --fs-instrument: 64px;

  /* shape & space */
  --r-ctl: 7px;
  --r-panel: 12px;
  --r-sheet: 16px;
  --band-h: 52px;
  --dock-clear: 104px;
  --gutter: 28px;

  /* depth (offset + soft blur, never a halo) */
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 24px rgba(0, 0, 0, 0.35);
  --shadow-2: 0 2px 6px rgba(0, 0, 0, 0.55), 0 24px 60px rgba(0, 0, 0, 0.55);

  /* motion */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-inout: cubic-bezier(0.65, 0, 0.35, 1);
  --t-fast: 140ms;
  --t-med: 260ms;
  --t-slow: 520ms;
}

@media (prefers-reduced-motion: reduce) {
  :root { --t-fast: 0ms; --t-med: 0ms; --t-slow: 0ms; }
}
@import "@fontsource-variable/mona-sans/wdth.css";
@import "./tokens.css";

*, *::before, *::after { box-sizing: border-box; }
html, body, #root { height: 100%; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  background-image:
    radial-gradient(1200px 600px at 12% -10%, var(--bg-glow), transparent 60%),
    radial-gradient(900px 500px at 100% 0%, rgba(77, 148, 255, 0.035), transparent 65%);
  background-attachment: fixed;
  color: var(--text);
  font-family: var(--font);
  font-size: var(--fs-body);
  line-height: 1.5;
  font-stretch: 100%;
  font-feature-settings: "ss01" 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

::selection { background: rgba(77, 148, 255, 0.38); color: #fff; }
:focus { outline: none; }
:focus-visible { outline: 2px solid var(--blue-hi); outline-offset: 2px; border-radius: 4px; }
input, textarea, select, button { font: inherit; color: inherit; }
button { cursor: pointer; background: none; border: 0; padding: 0; }
button:disabled { cursor: not-allowed; }
a { color: var(--blue-ink); text-decoration: none; text-underline-offset: 3px; }
a:hover { text-decoration: underline; }
h1, h2, h3, h4, p { margin: 0; }
h1, h2, h3 { text-wrap: balance; font-weight: 600; letter-spacing: -0.01em; }
p { text-wrap: pretty; }
input, textarea { caret-color: var(--blue-hi); }

* { scrollbar-width: thin; scrollbar-color: #2a2f39 transparent; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: #262b34; border-radius: 10px; border: 3px solid transparent; background-clip: padding-box; }
::-webkit-scrollbar-thumb:hover { background: #343a46; background-clip: padding-box; border: 3px solid transparent; }
::-webkit-scrollbar-track { background: transparent; }

/* ---------------------------------------------------------------- type helpers */
.num { font-variant-numeric: tabular-nums; }
.instrument {
  font-stretch: 118%;
  font-weight: 300;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.wide { font-stretch: 112%; }
.muted { color: var(--muted); }
.faint { color: var(--faint); }
.t-small { font-size: var(--fs-small); }
.t-micro { font-size: var(--fs-micro); letter-spacing: 0.01em; }
.t-lead { font-size: var(--fs-lead); line-height: 1.55; }
.t-title { font-size: var(--fs-title); font-weight: 600; letter-spacing: -0.01em; line-height: 1.25; }
.t-head { font-size: var(--fs-head); font-weight: 600; letter-spacing: -0.02em; line-height: 1.15; font-stretch: 106%; }
.ellipsis { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.id {
  font-size: var(--fs-small);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  font-stretch: 92%;
  letter-spacing: 0.02em;
}

/* ---------------------------------------------------------------- page frame */
.page {
  max-width: 1480px;
  margin: 0 auto;
  padding: calc(var(--band-h) + 28px) var(--gutter) var(--dock-clear);
}
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; margin-bottom: 22px; }
.page-head .lede { color: var(--text-2); max-width: 70ch; margin-top: 6px; }
@media (max-width: 720px) {
  :root { --gutter: 16px; }
  .page-head { flex-direction: column; align-items: flex-start; }
}

/* ---------------------------------------------------------------- panels (one level only — never nest) */
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--r-panel);
}
.panel-head {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 14px 18px 0;
  min-height: 44px;
}
.panel-head h2, .panel-head h3 { font-size: 14px; font-weight: 600; letter-spacing: 0; }
.panel-body { padding: 14px 18px 18px; }
.rule { height: 1px; background: var(--line); border: 0; margin: 0; }

/* ---------------------------------------------------------------- buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  height: 34px; padding: 0 14px;
  border-radius: var(--r-ctl);
  font-size: 13px; font-weight: 550;
  color: var(--text);
  background: var(--panel-2);
  border: 1px solid var(--line-2);
  transition: background var(--t-fast), border-color var(--t-fast), color var(--t-fast), transform var(--t-fast);
  white-space: nowrap;
}
.btn:hover:not(:disabled) { background: var(--hover); border-color: #353b47; }
.btn:active:not(:disabled) { transform: translateY(1px); background: var(--press); }
.btn:disabled { opacity: 0.45; }
.btn svg { width: 16px; height: 16px; flex: none; }
.btn-primary { background: var(--blue); border-color: var(--blue); color: #fff; }
.btn-primary:hover:not(:disabled) { background: #2477ea; border-color: #2477ea; }
.btn-ghost { background: transparent; border-color: transparent; color: var(--text-2); }
.btn-ghost:hover:not(:disabled) { background: var(--hover); border-color: transparent; color: var(--text); }
.btn-danger { color: var(--red-ink); }
.btn-danger:hover:not(:disabled) { background: var(--red-wash); border-color: rgba(255, 90, 95, 0.4); }
.btn-sm { height: 28px; padding: 0 10px; font-size: 12px; }
.btn-lg { height: 42px; padding: 0 18px; font-size: 14px; }
.btn-icon { width: 34px; padding: 0; }
.btn-sm.btn-icon { width: 28px; }

/* ---------------------------------------------------------------- inputs */
.input, .textarea, .select {
  width: 100%;
  background: #0a0c0f;
  border: 1px solid var(--line-2);
  border-radius: var(--r-ctl);
  color: var(--text);
  font-size: 13.5px;
  transition: border-color var(--t-fast), background var(--t-fast);
}
.input { height: 36px; padding: 0 12px; }
.textarea { padding: 10px 12px; line-height: 1.5; resize: vertical; min-height: 64px; }
.input:hover, .textarea:hover { border-color: #363c48; }
.input:focus, .textarea:focus { border-color: var(--blue-hi); background: #0b0e13; outline: none; }
.input::placeholder, .textarea::placeholder { color: var(--faint); }
.field-label { display: block; font-size: var(--fs-small); color: var(--muted); margin-bottom: 6px; font-weight: 500; }

/* ---------------------------------------------------------------- segmented control */
.seg {
  display: inline-flex; padding: 3px; gap: 2px;
  background: #0a0c0f; border: 1px solid var(--line); border-radius: 9px;
}
.seg button {
  height: 28px; padding: 0 12px; border-radius: 6px;
  font-size: 12.5px; font-weight: 550; color: var(--muted);
  transition: background var(--t-fast), color var(--t-fast);
  display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
}
.seg button:hover { color: var(--text); }
.seg button[aria-pressed="true"] { background: var(--panel-2); color: var(--text); box-shadow: 0 1px 2px rgba(0,0,0,.5), inset 0 0 0 1px var(--line-2); }
.seg .count { color: var(--faint); font-variant-numeric: tabular-nums; }

/* ---------------------------------------------------------------- chips & telltales */
.chip {
  display: inline-flex; align-items: center; gap: 5px;
  height: 22px; padding: 0 8px;
  border-radius: 6px;
  font-size: 11.5px; font-weight: 600; letter-spacing: 0.005em;
  background: rgba(255, 255, 255, 0.06); color: var(--text-2);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.chip svg { width: 12px; height: 12px; }
.chip.up { background: var(--green-wash); color: var(--green-ink); }
.chip.down { background: var(--red-wash); color: var(--red-ink); }
.chip.warn { background: var(--amber-wash); color: var(--amber-ink); }
.chip.blue { background: var(--blue-wash); color: var(--blue-ink); }
.chip.violet { background: var(--violet-wash); color: #d4c8ff; }
.chip.outline { background: transparent; box-shadow: inset 0 0 0 1px var(--line-2); color: var(--muted); }

.telltale { display: inline-flex; align-items: center; gap: 7px; font-size: var(--fs-small); color: var(--text-2); white-space: nowrap; }
.telltale::before {
  content: ""; width: 7px; height: 7px; border-radius: 50%;
  background: var(--tt, var(--faint));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--tt, var(--faint)) 22%, transparent);
}
.telltale.blue { --tt: var(--blue-hi); }
.telltale.amber { --tt: var(--amber); }
.telltale.red { --tt: var(--red); }
.telltale.green { --tt: var(--green); }
.telltale.violet { --tt: var(--violet); }

/* ---------------------------------------------------------------- tables */
.table { width: 100%; border-collapse: collapse; font-size: 13px; }
.table th {
  text-align: left; font-weight: 500; color: var(--muted); font-size: var(--fs-small);
  padding: 8px 12px; border-bottom: 1px solid var(--line); white-space: nowrap;
}
.table td { padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: middle; }
.table tr:last-child td { border-bottom: 0; }
.table tbody tr { transition: background var(--t-fast); }
.table tbody tr.clickable { cursor: pointer; }
.table tbody tr.clickable:hover { background: var(--hover); }
.table .r { text-align: right; font-variant-numeric: tabular-nums; }

/* ---------------------------------------------------------------- kbd */
.kbd {
  display: inline-grid; place-items: center; min-width: 20px; height: 20px; padding: 0 5px;
  border-radius: 5px; font-size: 11px; font-weight: 600; color: var(--muted);
  background: #0a0c0f; box-shadow: inset 0 0 0 1px var(--line-2), 0 1px 0 #000;
  font-variant-numeric: tabular-nums;
}

/* ---------------------------------------------------------------- skeleton */
.skel { position: relative; overflow: hidden; background: #12151a; border-radius: 6px; }
.skel::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.045), transparent);
  transform: translateX(-100%); animation: skel 1.4s var(--ease-inout) infinite;
}
@keyframes skel { to { transform: translateX(100%); } }

/* ---------------------------------------------------------------- utilities */
.row { display: flex; align-items: center; gap: 10px; }
.col { display: flex; flex-direction: column; gap: 10px; }
.wrap { flex-wrap: wrap; }
.grow { flex: 1; min-width: 0; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
// Instrument primitives shared by every screen. Each encodes one piece of state the same way everywhere:
// priority (fill = PM-confirmed, dashed = AI suggestion), evidence (signal bars), score (band-ticked bar / arc).
import type { ReactNode } from "react";
import { ArrowDownRight, ArrowUpRight, Minus } from "lucide-react";
import type { Evidence, Priority, Status } from "@/lib/types";
import { BANDS, EVIDENCE, EVIDENCE_HELP, STATUS } from "@/lib/labels";
import { fmtDelta, fmtScore } from "@/lib/format";
import "./ui.css";

export function PriorityMark({ p, ai, size = "md" }: { p: Priority | null | undefined; ai?: boolean; size?: "sm" | "md" }) {
  if (!p) return <span className={`pm pm-none pm-${size}`}>–</span>;
  return (
    <span
      className={`pm pm-${p.toLowerCase()} pm-${size}${ai ? " pm-ai" : ""}`}
      title={ai ? `${p} — AI suggests, not yet confirmed by the PM` : `${p} — confirmed by the PM`}
    >
      {p}
      {ai && <span className="pm-ai-tag">AI</span>}
    </span>
  );
}

export function EvidenceMeter({ level, label = false }: { level: Evidence | null | undefined; label?: boolean }) {
  const lit = level ? 5 - Number(level.slice(1)) : 0;
  const tone = lit >= 3 ? "good" : lit === 2 ? "mid" : "low";
  return (
    <span className="ev" title={level ? `${EVIDENCE[level]} — ${EVIDENCE_HELP[level]}` : "No evidence level"}>
      <span className={`ev-bars ev-${tone}`} aria-hidden>
        {[0, 1, 2, 3].map((i) => (
          <i key={i} className={i < lit ? "on" : ""} style={{ height: 4 + i * 3 }} />
        ))}
      </span>
      {label && <span className="ev-label">{level ? EVIDENCE[level] : "No level"}</span>}
      {!label && <span className="sr-only">{level ? EVIDENCE[level] : "No evidence level"}</span>}
    </span>
  );
}

export function ScoreBar({ score, width = 96, showValue = true }: { score: number | null | undefined; width?: number; showValue?: boolean }) {
  const s = score == null ? null : Math.max(0, Math.min(100, score));
  const band = s == null ? "none" : s >= BANDS.Must ? "must" : s >= BANDS.Should ? "should" : "could";
  return (
    <span className="sb" title={s == null ? "Not scored" : `Score ${s.toFixed(1)} of 100 · Must ≥ 60 · Should ≥ 45`}>
      <span className="sb-track" style={{ width }}>
        <span className={`sb-fill sb-${band}`} style={{ width: `${s ?? 0}%` }} />
        <span className="sb-tick" style={{ left: `${BANDS.Should}%` }} />
        <span className="sb-tick" style={{ left: `${BANDS.Must}%` }} />
      </span>
      {showValue && <span className="sb-val num">{fmtScore(s)}</span>}
    </span>
  );
}

/** Gauge for a headline score: 240° sweep, band ticks at Should/Must, wide light numerals. */
export function ScoreArc({ score, size = 168, caption }: { score: number | null | undefined; size?: number; caption?: ReactNode }) {
  const s = score == null ? 0 : Math.max(0, Math.min(100, score));
  const r = size / 2 - 10;
  const cx = size / 2;
  const cy = size / 2;
  const start = 150; // degrees, SVG coordinates (0 = 3 o'clock, clockwise)
  const sweep = 240;
  const pt = (deg: number, rr = r) => {
    const a = (deg * Math.PI) / 180;
    return [cx + rr * Math.cos(a), cy + rr * Math.sin(a)];
  };
  const arc = (from: number, to: number) => {
    const [x1, y1] = pt(from);
    const [x2, y2] = pt(to);
    const large = to - from > 180 ? 1 : 0;
    return `M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`;
  };
  const end = start + (sweep * s) / 100;
  const band = score == null ? "none" : s >= BANDS.Must ? "must" : s >= BANDS.Should ? "should" : "could";
  const tick = (v: number) => {
    const d = start + (sweep * v) / 100;
    const [x1, y1] = pt(d, r - 9);
    const [x2, y2] = pt(d, r + 6);
    return <line key={v} x1={x1} y1={y1} x2={x2} y2={y2} className="arc-tick" />;
  };
  return (
    <div className="arc" style={{ width: size, height: size * 0.86 }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-hidden>
        <path d={arc(start, start + sweep)} className="arc-track" />
        {score != null && s > 0.5 && <path d={arc(start, end)} className={`arc-fill arc-${band}`} />}
        {tick(BANDS.Should)}
        {tick(BANDS.Must)}
      </svg>
      <div className="arc-center">
        <div className="instrument arc-num" style={{ fontSize: size * 0.3 }}>{fmtScore(score)}</div>
        {caption && <div className="arc-cap">{caption}</div>}
      </div>
    </div>
  );
}

export function Delta({ d, digits }: { d: number | null | undefined; digits?: number }) {
  if (d == null) return <span className="chip outline">new</span>;
  const tone = d > 0.05 ? "up" : d < -0.05 ? "down" : "";
  const Icon = d > 0.05 ? ArrowUpRight : d < -0.05 ? ArrowDownRight : Minus;
  return (
    <span className={`chip ${tone}`}>
      <Icon aria-hidden />
      {digits === 0 ? `${d > 0 ? "+" : ""}${Math.round(d)}` : fmtDelta(d)}
    </span>
  );
}

const STATUS_TONE: Record<Status, string> = {
  proposed: "blue",
  challenged: "violet",
  approved: "green",
  deferred: "amber",
  rejected: "red",
};
export function StatusLight({ s }: { s: Status }) {
  return <span className={`telltale ${STATUS_TONE[s]}`}>{STATUS[s]}</span>;
}

export function Kbd({ children }: { children: ReactNode }) {
  return <kbd className="kbd">{children}</kbd>;
}

export function Seg<T extends string>({
  value,
  options,
  onChange,
  label,
}: {
  value: T;
  options: { value: T; label: ReactNode; count?: number }[];
  onChange: (v: T) => void;
  label: string;
}) {
  return (
    <div className="seg" role="group" aria-label={label}>
      {options.map((o) => (
        <button key={o.value} type="button" aria-pressed={o.value === value} onClick={() => onChange(o.value)}>
          {o.label}
          {o.count != null && <span className="count">{o.count}</span>}
        </button>
      ))}
    </div>
  );
}

export function Skeleton({ h = 14, w = "100%", r }: { h?: number; w?: number | string; r?: number }) {
  return <div className="skel" style={{ height: h, width: w, borderRadius: r }} />;
}

export function SkeletonBlock({ lines = 4 }: { lines?: number }) {
  return (
    <div className="col" style={{ gap: 10 }}>
      {Array.from({ length: lines }).map((_, i) => (
        <Skeleton key={i} w={`${92 - ((i * 17) % 40)}%`} />
      ))}
    </div>
  );
}

export function ErrorNote({ error, onRetry }: { error: unknown; onRetry?: () => void }) {
  const msg = error instanceof Error ? error.message : String(error);
  return (
    <div className="errnote" role="alert">
      <span className="telltale red">Couldn't load</span>
      <span className="errnote-msg">{msg}</span>
      {onRetry && (
        <button className="btn btn-sm" onClick={onRetry}>
          Try again
        </button>
      )}
    </div>
  );
}

export function Empty({ title, children }: { title: string; children?: ReactNode }) {
  return (
    <div className="empty">
      <div className="empty-title">{title}</div>
      {children && <div className="empty-body">{children}</div>}
    </div>
  );
}

export function Stat({ label, value, sub }: { label: string; value: ReactNode; sub?: ReactNode }) {
  return (
    <div className="stat">
      <div className="stat-label">{label}</div>
      <div className="stat-value num">{value}</div>
      {sub && <div className="stat-sub">{sub}</div>}
    </div>
  );
}
/* ---------------------------------------------------------------- priority mark */
.pm {
  display: inline-flex; align-items: center; gap: 5px;
  height: 22px; padding: 0 9px; border-radius: 6px;
  font-size: 11.5px; font-weight: 650; letter-spacing: 0.01em; white-space: nowrap;
  font-stretch: 104%;
}
.pm-sm { height: 19px; padding: 0 7px; font-size: 11px; }
.pm-must { background: var(--blue); color: #fff; }
.pm-should { background: transparent; color: var(--blue-ink); box-shadow: inset 0 0 0 1px var(--blue-line); }
.pm-could { background: transparent; color: var(--muted); box-shadow: inset 0 0 0 1px var(--line-2); }
.pm-none { color: var(--faint); padding: 0 4px; }
.pm-ai { box-shadow: none; outline: 1px dashed currentColor; outline-offset: -1px; }
.pm-must.pm-ai { background: var(--blue-wash); color: var(--blue-ink); outline-color: var(--blue-hi); }
.pm-should.pm-ai { outline-color: var(--blue-line); }
.pm-could.pm-ai { outline-color: #3a404c; }
.pm-ai-tag { font-size: 9px; font-weight: 700; letter-spacing: 0.06em; opacity: 0.8; }

/* ---------------------------------------------------------------- evidence meter (signal bars) */
.ev { display: inline-flex; align-items: center; gap: 7px; white-space: nowrap; }
.ev-bars { display: inline-flex; align-items: flex-end; gap: 2px; height: 13px; }
.ev-bars i { display: block; width: 3px; border-radius: 1px; background: #2a2f39; }
.ev-good i.on { background: var(--green); }
.ev-mid i.on { background: var(--amber); }
.ev-low i.on { background: var(--red); }
.ev-label { font-size: var(--fs-small); color: var(--text-2); }

/* ---------------------------------------------------------------- score bar */
.sb { display: inline-flex; align-items: center; gap: 8px; }
.sb-track { position: relative; height: 4px; border-radius: 2px; background: #1e222a; overflow: visible; flex: none; }
.sb-fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 2px; transition: width var(--t-slow) var(--ease-out); }
.sb-must { background: var(--blue-hi); }
.sb-should { background: #3f6fb0; }
.sb-could { background: #4b5261; }
.sb-tick { position: absolute; top: -2px; width: 1px; height: 8px; background: #545c6b; }
.sb-val { font-size: 12.5px; color: var(--text-2); min-width: 20px; text-align: right; }

/* ---------------------------------------------------------------- score arc */
.arc { position: relative; flex: none; }
.arc svg { position: absolute; inset: 0; overflow: visible; }
.arc-track { fill: none; stroke: #1c2028; stroke-width: 6; stroke-linecap: round; }
.arc-fill { fill: none; stroke-width: 6; stroke-linecap: round; transition: d var(--t-slow) var(--ease-out); }
.arc-must { stroke: var(--blue-hi); filter: drop-shadow(0 2px 6px rgba(77, 148, 255, 0.35)); }
.arc-should { stroke: #4d7fc4; }
.arc-could { stroke: #5a6272; }
.arc-tick { stroke: #6a7383; stroke-width: 1.5; }
.arc-center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; padding-top: 6px; }
.arc-num { color: #fff; }
.arc-cap { margin-top: 6px; font-size: var(--fs-small); color: var(--muted); }

/* ---------------------------------------------------------------- notes */
.errnote { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: var(--r-ctl); background: var(--red-wash); flex-wrap: wrap; }
.errnote-msg { color: var(--red-ink); font-size: 13px; flex: 1; min-width: 200px; }
.empty { padding: 28px 8px; text-align: center; }
.empty-title { font-weight: 600; color: var(--text-2); }
.empty-body { color: var(--muted); margin-top: 6px; font-size: 13px; max-width: 52ch; margin-inline: auto; }

/* ---------------------------------------------------------------- stat */
.stat-label { font-size: var(--fs-small); color: var(--muted); }
.stat-value { font-size: 22px; font-weight: 500; font-stretch: 112%; letter-spacing: -0.01em; margin-top: 2px; }
.stat-sub { font-size: var(--fs-small); color: var(--faint); margin-top: 2px; }

