// App chrome: the panoramic status band (top) and the floating dock (bottom). The band answers "where are we in
// the 2-year process, what's waiting, what has it cost" from any screen.
import { useEffect, useState, type ReactNode } from "react";
import { NavLink, useLocation, useNavigate } from "react-router-dom";
import { motion } from "motion/react";
import { Archive, Car, Command, Gauge, Globe2, Inbox, Search, Workflow } from "lucide-react";
import { useAppState, useMeta } from "@/lib/hooks";
import { getActor, setActor } from "@/lib/api";
import { fmtSimDate, fmtUsd } from "@/lib/format";
import "./shell.css";

type NavItem = { to: string; label: string; icon: typeof Gauge; key: string; end?: boolean };
export const NAV: NavItem[] = [
  { to: "/", label: "Briefing", icon: Gauge, key: "1", end: true },
  { to: "/decide", label: "Decide", icon: Inbox, key: "2" },
  { to: "/cars", label: "Cars", icon: Car, key: "3" },
  { to: "/markets", label: "Markets", icon: Globe2, key: "4" },
  { to: "/evidence", label: "Evidence", icon: Archive, key: "5" },
  { to: "/process", label: "Process", icon: Workflow, key: "6" },
];

function Mark() {
  // Successor mark: an instrument arc with a forward tick — no third-party trademark.
  return (
    <svg width="22" height="22" viewBox="0 0 24 24" aria-hidden className="mark">
      <path d="M4.2 16.5a8.5 8.5 0 1 1 15.6 0" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M12 12.6 16.6 8" stroke="var(--blue-hi)" strokeWidth="2.2" strokeLinecap="round" />
      <circle cx="12" cy="12.6" r="1.7" fill="var(--blue-hi)" />
    </svg>
  );
}

function WaveStrip() {
  const { data: s } = useAppState();
  const { data: meta } = useMeta();
  const waves = meta ? Object.entries(meta.waves) : [];
  const cur = s?.current_wave ?? 0;
  return (
    <NavLink to="/process" className="wave-strip" title="The ~2-year requirements process, replayed as three evidence waves">
      <span className="sim">Simulation</span>
      <span className="wave-ticks" aria-hidden>
        {waves.map(([n]) => (
          <i key={n} className={Number(n) < cur ? "done" : Number(n) === cur ? "now" : ""} />
        ))}
      </span>
      {s?.running_job ? (
        <span className="telltale blue pulse">{s.running_job.kind === "wave" ? "Opening next wave…" : "AI is answering…"}</span>
      ) : s?.wave ? (
        <span className="wave-text">
          <b>Wave {cur}</b>
          <span className="muted"> · {s.wave.label.replace(/^Wave \d+ · /, "")} · {fmtSimDate(s.wave.simulated_date)}</span>
        </span>
      ) : (
        <span className="muted">No wave opened</span>
      )}
    </NavLink>
  );
}

function ActorChip() {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(getActor());
  const initials = name
    .replace(/\(.*\)/, "")
    .trim()
    .split(/\s+/)
    .map((w) => w[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
  if (editing)
    return (
      <form
        className="actor-edit"
        onSubmit={(e) => {
          e.preventDefault();
          const v = name.trim() || "Atahan (PM)";
          setActor(v);
          setName(v);
          setEditing(false);
        }}
      >
        <input className="input" autoFocus value={name} onChange={(e) => setName(e.target.value)} onBlur={() => setEditing(false)} aria-label="Acting as" />
      </form>
    );
  return (
    <button className="actor" onClick={() => setEditing(true)} title="Acting as — the named person recorded on every decision. Click to change.">
      <span className="avatar">{initials || "PM"}</span>
      <span className="actor-name">{name}</span>
    </button>
  );
}

function Spend() {
  const { data: s } = useAppState();
  if (!s) return null;
  const pct = Math.min(100, (s.spend_usd / s.budget.total) * 100);
  return (
    <NavLink to="/process?tab=system" className="spend" title={`OpenAI spend ${fmtUsd(s.spend_usd)} of $${s.budget.total} — hard stop at $${s.budget.hard_stop}`}>
      <span className="spend-val num">{fmtUsd(s.spend_usd)}</span>
      <span className="spend-track">
        <span style={{ width: `${pct}%` }} />
        <i style={{ left: `${(s.budget.warn / s.budget.total) * 100}%` }} />
        <i style={{ left: `${(s.budget.hard_stop / s.budget.total) * 100}%` }} />
      </span>
    </NavLink>
  );
}

export function Band({ onOpenPalette }: { onOpenPalette: () => void }) {
  const { data: s } = useAppState();
  const waiting = s ? s.counts.to_review + s.counts.open_proposals : 0;
  return (
    <header className="band">
      <div className="band-left">
        <NavLink to="/" className="brand" aria-label="Successor — briefing">
          <Mark />
          <span className="brand-name">Successor</span>
        </NavLink>
        <span className="band-sep" />
        <WaveStrip />
      </div>
      <div className="band-right">
        {waiting > 0 && (
          <NavLink to="/decide" className="waiting" title="Requirements to review and AI suggestions waiting for your decision">
            <span className="waiting-n num">{waiting}</span> waiting for you
          </NavLink>
        )}
        <Spend />
        <ActorChip />
        <button className="btn btn-sm palette-btn" onClick={onOpenPalette} aria-label="Search and commands">
          <Search />
          <span className="kbd">⌘K</span>
        </button>
      </div>
    </header>
  );
}

export function Dock({ onOpenPalette }: { onOpenPalette: () => void }) {
  const { data: s } = useAppState();
  const loc = useLocation();
  const nav = useNavigate();
  const waiting = s ? s.counts.to_review + s.counts.open_proposals : 0;

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const item = NAV.find((n) => n.key === e.key);
      if (item && !loc.pathname.startsWith("/decide")) {
        e.preventDefault();
        nav(item.to);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [nav, loc.pathname]);

  return (
    <nav className="dock-wrap" aria-label="Main">
      <div className="dock">
        {NAV.map((n) => {
          const active = n.end ? loc.pathname === "/" : loc.pathname.startsWith(n.to);
          return (
            <NavLink key={n.to} to={n.to} end={n.end} className={`dock-item${active ? " active" : ""}`} title={`${n.label}  (${n.key})`}>
              {active && <motion.span layoutId="dock-active" className="dock-active" transition={{ type: "spring", stiffness: 500, damping: 40 }} />}
              <n.icon aria-hidden />
              <span className="dock-label">{n.label}</span>
              {n.to === "/decide" && waiting > 0 && <span className="dock-badge num">{waiting}</span>}
            </NavLink>
          );
        })}
      </div>
      <button className="dock-search" onClick={onOpenPalette} aria-label="Search and commands (⌘K)">
        <Command aria-hidden />
      </button>
    </nav>
  );
}

export function PageHead({ title, lede, actions }: { title: ReactNode; lede?: ReactNode; actions?: ReactNode }) {
  return (
    <div className="page-head">
      <div>
        <h1 className="t-head">{title}</h1>
        {lede && <p className="lede">{lede}</p>}
      </div>
      {actions && <div className="row wrap">{actions}</div>}
    </div>
  );
}
import { useEffect, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "motion/react";
import { X } from "lucide-react";

/** Right-hand sheet for detail that shouldn't cost the PM their place (evidence, findings, sources). */
export function Drawer({ open, onClose, title, sub, children, width }: { open: boolean; onClose: () => void; title: ReactNode; sub?: ReactNode; children: ReactNode; width?: number }) {
  useEffect(() => {
    if (!open) return;
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, onClose]);
  return createPortal(
    <AnimatePresence>
      {open && (
        <>
          <motion.div className="drawer-scrim" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={onClose} />
          <motion.aside
            className="drawer"
            role="dialog"
            aria-modal="true"
            style={width ? { width: `min(${width}px, calc(100vw - 20px))` } : undefined}
            initial={{ x: 40, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: 30, opacity: 0, transition: { duration: 0.16 } }}
            transition={{ duration: 0.34, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="drawer-head">
              <div className="grow">
                <div className="t-title">{title}</div>
                {sub && <div className="muted t-small" style={{ marginTop: 4 }}>{sub}</div>}
              </div>
              <button className="btn btn-ghost btn-icon btn-sm" onClick={onClose} aria-label="Close">
                <X />
              </button>
            </div>
            <div className="drawer-body">{children}</div>
          </motion.aside>
        </>
      )}
    </AnimatePresence>,
    document.body,
  );
}
// PM write actions with their guard rails: every one needs a reason (≥5 characters, server-enforced too),
// and long AI jobs run in the background with visible progress.
import { useEffect, useState } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { Sparkles } from "lucide-react";
import { api, invalidateAll } from "@/lib/api";
import type { ChallengeAnswer, Job } from "@/lib/types";
import { VERDICT } from "@/lib/labels";
import { Drawer } from "./Drawer";
import { useToast } from "./toast";

export const MIN_REASON = 5;
export const reasonOk = (s: string) => s.trim().length >= MIN_REASON;

export function useJob(id: string | null) {
  return useQuery({
    queryKey: ["job", id],
    queryFn: () => api.get<Job>(`/api/jobs/${id}`),
    enabled: !!id,
    refetchInterval: (q) => (q.state.data && q.state.data.status !== "running" ? false : 1500),
  });
}

export function ReasonField({ value, onChange, placeholder, id, autoFocus }: { value: string; onChange: (s: string) => void; placeholder: string; id: string; autoFocus?: boolean }) {
  const short = value.length > 0 && !reasonOk(value);
  return (
    <div>
      <label className="field-label" htmlFor={id}>
        Reason <span className="faint">— recorded with your name in the audit trail</span>
      </label>
      <textarea id={id} className="textarea" rows={2} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} autoFocus={autoFocus} />
      {short && <div className="t-small" style={{ color: "var(--amber-ink)", marginTop: 4 }}>A few more words, please — at least {MIN_REASON} characters.</div>}
    </div>
  );
}

export function OverrideDrawer({ reqId, target, label, onClose }: { reqId: string; target: string | null; label: string; onClose: () => void }) {
  const [why, setWhy] = useState("");
  const toast = useToast();
  const m = useMutation({
    mutationFn: () => api.post(`/api/requirements/${reqId}/override`, { target, rationale: why }),
    onSuccess: () => {
      toast({ tone: "ok", title: "Gate overridden", body: `${label} — recorded in the audit trail.` });
      invalidateAll();
      onClose();
    },
    onError: (e: Error) => toast({ tone: "error", title: "Not overridden", body: e.message }),
  });
  return (
    <Drawer open={!!target} onClose={onClose} title={`Override the brand gate · ${label}`} sub="The AI found a brand-fit problem. You can approve anyway, but only with a reason.">
      <div className="col" style={{ gap: 14 }}>
        <ReasonField id="ov-why" value={why} onChange={setWhy} placeholder="Why this still fits the brand for this car and market…" autoFocus />
        <div className="row">
          <button className="btn btn-danger" disabled={!reasonOk(why) || m.isPending} onClick={() => m.mutate()}>
            Override gate
          </button>
          <button className="btn btn-ghost" onClick={onClose}>
            Cancel
          </button>
        </div>
      </div>
    </Drawer>
  );
}

/** "Ask the AI": the PM challenges a requirement; the answer can propose edits and evidence links (proposals). */
export function ChallengeDrawer({ reqId, open, onClose }: { reqId: string; open: boolean; onClose: () => void }) {
  const [q, setQ] = useState("");
  const [jobId, setJobId] = useState<string | null>(null);
  const job = useJob(jobId);
  const toast = useToast();
  const start = useMutation({
    mutationFn: () => api.post<{ job_id: string }>(`/api/requirements/${reqId}/challenge`, { question: q }),
    onSuccess: (r) => setJobId(r.job_id),
    onError: (e: Error) => toast({ tone: "error", title: "Couldn't ask the AI", body: e.message }),
  });
  useEffect(() => {
    if (job.data?.status === "done") invalidateAll();
  }, [job.data?.status]);
  useEffect(() => {
    if (!open) {
      setJobId(null);
      setQ("");
    }
  }, [open]);
  const res = (job.data?.result ?? null) as { answer?: ChallengeAnswer; cost?: number } | null;
  const a = res?.answer;
  return (
    <Drawer open={open} onClose={onClose} title="Ask the AI" sub="Challenge the requirement. The status becomes Challenged; any edits the AI suggests arrive as proposals you decide on.">
      {!jobId && (
        <div className="col" style={{ gap: 14 }}>
          <div>
            <label className="field-label" htmlFor="ch-q">Your question</label>
            <textarea id="ch-q" className="textarea" rows={4} value={q} onChange={(e) => setQ(e.target.value)} autoFocus placeholder="e.g. Is there evidence that Chinese customers want this, or is it a US pain point?" />
          </div>
          <div className="row">
            <button className="btn btn-primary" disabled={!reasonOk(q) || start.isPending} onClick={() => start.mutate()}>
              <Sparkles /> Ask · costs a few cents
            </button>
            <span className="t-small faint">Takes 20–60 seconds.</span>
          </div>
        </div>
      )}
      {jobId && job.data?.status === "running" && (
        <div className="col" style={{ gap: 12 }}>
          <span className="telltale blue pulse">The AI is re-reading the evidence…</span>
          <div className="skel" style={{ height: 4 }} />
        </div>
      )}
      {job.data?.status === "error" && <div className="errnote"><span className="errnote-msg">{job.data.error}</span></div>}
      {a && (
        <div className="col" style={{ gap: 16 }}>
          <span className={`chip ${a.verdict === "upheld" ? "up" : a.verdict === "partially_upheld" ? "warn" : "blue"}`} style={{ alignSelf: "flex-start" }}>
            {VERDICT[a.verdict] ?? a.verdict}
          </span>
          <p className="t-lead">{a.answer}</p>
          {a.evidence_for.length > 0 && (
            <div>
              <div className="sec-label">Evidence for</div>
              <ul className="sw-list">{a.evidence_for.map((x) => <li key={x}>{x}</li>)}</ul>
            </div>
          )}
          {a.evidence_against.length > 0 && (
            <div>
              <div className="sec-label">Evidence against</div>
              <ul className="sw-list">{a.evidence_against.map((x) => <li key={x}>{x}</li>)}</ul>
            </div>
          )}
          {(a.proposed_edits.length > 0 || a.link_finding_ids.length > 0) && (
            <p className="t-small muted">
              {a.proposed_edits.length} edit(s) and {a.link_finding_ids.length} evidence link(s) were proposed — they are in your Decide queue.
            </p>
          )}
        </div>
      )}
    </Drawer>
  );
}
// Confirmation for every recorded decision: what was written and that it's in the audit trail.
import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from "react";
import { AnimatePresence, motion } from "motion/react";
import { Check, X } from "lucide-react";

type Toast = { id: number; title: string; body?: string; tone: "ok" | "error" };
const Ctx = createContext<{ push: (t: Omit<Toast, "id">) => void }>({ push: () => {} });

export function ToastProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<Toast[]>([]);
  const push = useCallback((t: Omit<Toast, "id">) => {
    const id = Date.now() + Math.random();
    setItems((xs) => [...xs.slice(-2), { ...t, id }]);
    setTimeout(() => setItems((xs) => xs.filter((x) => x.id !== id)), t.tone === "error" ? 8000 : 4200);
  }, []);
  const value = useMemo(() => ({ push }), [push]);
  return (
    <Ctx.Provider value={value}>
      {children}
      <div className="toasts" aria-live="polite">
        <AnimatePresence initial={false}>
          {items.map((t) => (
            <motion.div
              key={t.id}
              className={`toast toast-${t.tone}`}
              initial={{ opacity: 0, y: 12, filter: "blur(4px)" }}
              animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
              exit={{ opacity: 0, y: 8, transition: { duration: 0.18 } }}
              transition={{ duration: 0.32, ease: [0.16, 1, 0.3, 1] }}
            >
              <span className="toast-icon">{t.tone === "ok" ? <Check /> : <X />}</span>
              <div>
                <div className="toast-title">{t.title}</div>
                {t.body && <div className="toast-body">{t.body}</div>}
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </Ctx.Provider>
  );
}

export const useToast = () => useContext(Ctx).push;
// Thin client for the local Successor API (`api/`, FastAPI). Every write carries the acting PM in X-Actor;
// the server records it in the append-only audit trail.
import { QueryClient } from "@tanstack/react-query";

const ACTOR_KEY = "successor.actor";
export const DEFAULT_ACTOR = "Atahan (PM)";

export function getActor(): string {
  try {
    return localStorage.getItem(ACTOR_KEY) || DEFAULT_ACTOR;
  } catch {
    return DEFAULT_ACTOR;
  }
}
export function setActor(name: string) {
  try {
    localStorage.setItem(ACTOR_KEY, name);
  } catch {
    /* private mode: fall back to the default actor */
  }
}

export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, {
      method,
      headers: { "Content-Type": "application/json", "X-Actor": getActor() },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    throw new ApiError(0, "The local API isn't reachable. Start it with `uv run python -m api`.");
  }
  if (!res.ok) {
    let msg = `${res.status} ${res.statusText}`;
    try {
      const j = await res.json();
      if (typeof j.detail === "string") msg = j.detail;
      else if (Array.isArray(j.detail)) msg = j.detail.map((d: { msg?: string }) => d.msg).join("; ");
    } catch {
      /* keep status text */
    }
    throw new ApiError(res.status, msg);
  }
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

export const api = {
  get: <T,>(path: string) => request<T>("GET", path),
  post: <T,>(path: string, body?: unknown) => request<T>("POST", path, body ?? {}),
  put: <T,>(path: string, body?: unknown) => request<T>("PUT", path, body ?? {}),
  patch: <T,>(path: string, body?: unknown) => request<T>("PATCH", path, body ?? {}),
};

export function qs(params: Record<string, string | number | boolean | null | undefined>): string {
  const u = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== null && v !== "") u.set(k, String(v));
  const s = u.toString();
  return s ? `?${s}` : "";
}

export const queryClient = new QueryClient({
  defaultOptions: { queries: { staleTime: 15_000, refetchOnWindowFocus: false, retry: 1 } },
});

/** Everything a decision can change; refetched after every write. */
export function invalidateAll() {
  return queryClient.invalidateQueries();
}
export const fmtScore = (s: number | null | undefined) => (s == null ? "–" : Math.round(s).toString());
export const fmtDelta = (d: number | null | undefined) => (d == null ? "–" : `${d > 0 ? "+" : d < 0 ? "−" : "±"}${Math.abs(d).toFixed(1)}`);
export const fmtUsd = (n: number) => `$${n.toFixed(2)}`;
export const fmtInt = (n: number | null | undefined) => (n == null ? "–" : n.toLocaleString("en-US"));
export const fmtPct = (n: number | null | undefined, digits = 1) => (n == null ? "–" : `${(n * 100).toFixed(digits)}%`);

export function fmtWhen(ts: string | null | undefined): string {
  if (!ts) return "–";
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return ts;
  return d.toLocaleString("en-GB", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });
}

export function fmtSimDate(s: string | null | undefined): string {
  if (!s) return "";
  const [y, m] = s.split("-");
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return m ? `${months[Number(m) - 1]} ${y}` : s;
}

/** Split a markdown bullet string ("- a\n- b") into items. */
export function bullets(s: string | null | undefined): string[] {
  if (!s) return [];
  return s
    .split(/\n+/)
    .map((l) => l.replace(/^\s*[-*•]\s*/, "").trim())
    .filter(Boolean);
}

export const plural = (n: number, one: string, many = `${one}s`) => `${n.toLocaleString("en-US")} ${n === 1 ? one : many}`;
