1	// Decide: ONE queue for everything that needs the PM — AI priority changes on decided items, merges, new
2	// requirements to review, AI edits from challenges. Step through it like a rotary controller (J/K), decide with
3	// a reason, and the next item rolls in. The AI never applies anything itself.
4	import { useEffect, useMemo, useRef, useState } from "react";
5	import { Link, useNavigate, useParams } from "react-router-dom";
6	import { useMutation, useQuery } from "@tanstack/react-query";
7	import { AnimatePresence, motion } from "motion/react";
8	import { ArrowRight, Check, Clock, ExternalLink, GitMerge, MessageCircleQuestion, PencilLine, SlidersHorizontal, Sparkles, X } from "lucide-react";
9	import { api, invalidateAll, qs } from "@/lib/api";
10	import type { Meta, Priority, Proposal, QueueItem, RequirementDetail } from "@/lib/types";
11	import { PROPOSAL_KIND, targetLabel } from "@/lib/labels";
12	import { fmtWhen } from "@/lib/format";
13	import { useMeta } from "@/lib/hooks";
14	import { Empty, ErrorNote, Kbd, PriorityMark, ScoreBar, SkeletonBlock, StatusLight } from "@/components/ui";
15	import { AssumptionsBlock, Conflict, DecisionAsk, FitGates, MarketTable, Quotes, ReqTags, StudyAndWeb, VoiceByMarket } from "@/components/req";
16	import { ChallengeDrawer, OverrideDrawer, ReasonField, reasonOk } from "@/components/actions";
17	import { useToast } from "@/components/toast";
18	import "./decide.css";
19	
20	type Queue = { items: QueueItem[]; counts: Record<string, number> };
21	
22	const GROUPS: { id: string; label: string; kinds: QueueItem["kind"][]; icon: typeof Clock }[] = [
23	  { id: "changes", label: "Changes to your decisions", kinds: ["priority"], icon: SlidersHorizontal },
24	  { id: "merge", label: "Merge into existing", kinds: ["extend"], icon: GitMerge },
25	  { id: "review", label: "To review", kinds: ["review", "challenged", "new_requirement"], icon: Clock },
26	  { id: "edits", label: "AI edits & evidence", kinds: ["content", "link_finding"], icon: PencilLine },
27	];
28	
29	const isTyping = (e: KeyboardEvent) => {
30	  const t = e.target as HTMLElement;
31	  return t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT" || t.isContentEditable);
32	};
33	
34	export default function Decide() {
35	  const { uid } = useParams();
36	  const nav = useNavigate();
37	  const { data: meta } = useMeta();
38	  const [scope, setScope] = useState<string>("");
39	  const q = useQuery({ queryKey: ["queue", scope], queryFn: () => api.get<Queue>(`/api/queue${qs({ target: scope })}`) });
40	  const items = q.data?.items ?? [];
41	  const ordered = useMemo(() => GROUPS.flatMap((g) => items.filter((i) => g.kinds.includes(i.kind))).concat(items.filter((i) => !GROUPS.some((g) => g.kinds.includes(i.kind)))), [items]);
42	  const idx = Math.max(0, ordered.findIndex((i) => i.uid === uid));
43	  const current = ordered.find((i) => i.uid === uid) ?? ordered[0] ?? null;
44	  const [dir, setDir] = useState(1);
45	  const lastUid = useRef<string | null>(null);
46	
47	  const goTo = (i: number) => {
48	    const it = ordered[Math.max(0, Math.min(ordered.length - 1, i))];
49	    if (!it) return;
50	    setDir(i >= idx ? 1 : -1);
51	    nav(`/decide/${encodeURIComponent(it.uid)}`, { replace: true });
52	  };
53	
54	  useEffect(() => {
55	    const k = (e: KeyboardEvent) => {
56	      if (isTyping(e) || e.metaKey || e.ctrlKey || e.altKey) return;
57	      if (e.key === "j" || e.key === "ArrowDown") {
58	        e.preventDefault();
59	        goTo(idx + 1);
60	      } else if (e.key === "k" || e.key === "ArrowUp") {
61	        e.preventDefault();
62	        goTo(idx - 1);
63	      }
64	    };
65	    window.addEventListener("keydown", k);
66	    return () => window.removeEventListener("keydown", k);
67	  });
68	
69	  // after a decision the item leaves the queue: roll to whatever now sits at the same position
70	  const afterDecision = (decidedUid: string) => {
71	    lastUid.current = decidedUid;
72	    setDir(1);
73	    const rest = ordered.filter((i) => i.uid !== decidedUid);
74	    const next = rest[Math.min(idx, rest.length - 1)];
75	    nav(next ? `/decide/${encodeURIComponent(next.uid)}` : "/decide", { replace: true });
76	  };
77	
78	  return (
79	    <main className="page decide">
80	      <aside className="qrail" aria-label="Decision queue">
81	        <div className="qrail-head">
82	          <div>
83	            <h1 className="t-title">Decide</h1>
84	            <p className="muted t-small">{ordered.length ? `${idx + 1} of ${ordered.length} waiting` : "Queue empty"}</p>
85	          </div>
86	          <select className="select qscope" value={scope} onChange={(e) => setScope(e.target.value)} aria-label="Limit the queue to one car · market">
87	            <option value="">All cars & markets</option>
88	            {meta?.targets.map((t) => (
89	              <option key={t.key} value={t.key}>
90	                {t.label}
91	              </option>
92	            ))}
93	          </select>
94	        </div>
95	        {q.isLoading && <SkeletonBlock lines={8} />}
96	        {q.isError && <ErrorNote error={q.error} onRetry={() => q.refetch()} />}
97	        <div className="qrail-list">
98	          {GROUPS.map((g) => {
99	            const gi = ordered.filter((i) => g.kinds.includes(i.kind));
100	            if (!gi.length) return null;
101	            return (
102	              <section key={g.id} className="qgroup">
103	                <h2 className="qgroup-h">
104	                  <g.icon aria-hidden /> {g.label} <span className="num faint">{gi.length}</span>
105	                </h2>
106	                {gi.map((it) => (
107	                  <button
108	                    key={it.uid}
109	                    className={`qitem${current?.uid === it.uid ? " on" : ""}`}
110	                    onClick={() => {
111	                      setDir(ordered.indexOf(it) >= idx ? 1 : -1);
112	                      nav(`/decide/${encodeURIComponent(it.uid)}`, { replace: true });
113	                    }}
114	                    aria-current={current?.uid === it.uid}
115	                  >
116	                    <span className="qitem-title">{it.title}</span>
117	                    <span className="qitem-sub">
118	                      {it.kind === "priority" && it.target ? (
119	                        <>
120	                          {it.target.label} · <PriorityMark p={it.priority} size="sm" ai />
121	                        </>
122	                      ) : (
123	                        <>
124	                          {it.is_new_in_wave && <span className="chip blue">new</span>}
125	                          {it.kind === "challenged" && <span className="chip violet">challenged</span>}
126	                          <span className="ellipsis">{it.subtitle}</span>
127	                        </>
128	                      )}
129	                      {it.score != null && it.kind !== "priority" && <ScoreBar score={it.score} width={36} />}
130	                    </span>
131	                  </button>
132	                ))}
133	              </section>
134	            );
135	          })}
136	        </div>
137	        <div className="qrail-keys faint t-micro">
138	          <Kbd>J</Kbd> <Kbd>K</Kbd> step · <Kbd>⌘</Kbd>
139	          <Kbd>↵</Kbd> record
140	        </div>
141	      </aside>
142	
143	      <section className="workspace" aria-live="polite">
144	        {!q.isLoading && !current && (
145	          <div className="panel ws-empty">
146	            <Empty title="Nothing waiting for you">
147	              Every requirement has a decision and every AI suggestion is answered. New evidence arrives with the next wave — see <Link to="/process">Process</Link>.
148	            </Empty>
149	          </div>
150	        )}
151	        <AnimatePresence mode="popLayout" initial={false} custom={dir}>
152	          {current && (
153	            <motion.div
154	              key={current.uid}
155	              custom={dir}
156	              variants={{
157	                enter: (d: number) => ({ opacity: 0, y: d * 28, filter: "blur(3px)" }),
158	                center: { opacity: 1, y: 0, filter: "blur(0px)" },
159	                exit: (d: number) => ({ opacity: 0, y: d * -22, filter: "blur(3px)", transition: { duration: 0.18 } }),
160	              }}
161	              initial="enter"
162	              animate="center"
163	              exit="exit"
164	              transition={{ duration: 0.36, ease: [0.16, 1, 0.3, 1] }}
165	            >
166	              {current.type === "requirement" ? (
167	                <ReviewItem item={current} meta={meta} onDone={() => afterDecision(current.uid)} />
168	              ) : (
169	                <ProposalItem item={current} onDone={() => afterDecision(current.uid)} siblings={ordered.filter((i) => i.kind === current.kind)} />
170	              )}
171	            </motion.div>
172	          )}
173	        </AnimatePresence>
174	      </section>
175	    </main>
176	  );
177	}
178	
179	/* ================================================================ review a requirement */
180	
181	type Choice = "approved" | "deferred" | "rejected";
182	const CHOICES: { v: Choice; label: string; key: string; icon: typeof Check; tone: string }[] = [
183	  { v: "approved", label: "Approve", key: "A", icon: Check, tone: "approve" },
184	  { v: "deferred", label: "Defer", key: "D", icon: Clock, tone: "defer" },
185	  { v: "rejected", label: "Reject", key: "R", icon: X, tone: "reject" },
186	];
187	
188	function ReviewItem({ item, onDone }: { item: QueueItem; meta?: Meta; onDone: () => void }) {
189	  const q = useQuery({ queryKey: ["requirement", item.req_id], queryFn: () => api.get<RequirementDetail>(`/api/requirements/${item.req_id}`) });
190	  const r = q.data;
191	  const toast = useToast();
192	  const [choice, setChoice] = useState<Choice | null>(null);
193	  const [why, setWhy] = useState("");
194	  const [draft, setDraft] = useState<Record<string, Priority | null>>({});
195	  const [acceptAi, setAcceptAi] = useState(true);
196	  const [override, setOverride] = useState<string | null>(null);
197	  const [ask, setAsk] = useState(false);
198	  const reasonRef = useRef<HTMLDivElement>(null);
199	
200	  useEffect(() => {
201	    api.post("/api/access", { action: "view", entity_type: "requirement", entity_id: item.req_id }).catch(() => {});
202	  }, [item.req_id]);
203	
204	  const blocked = r?.brand_blocked ?? [];
205	  const unset = r ? r.targets.filter((t) => !t.pm_priority && t.ai_priority && !(t.target.key in draft)).length : 0;
206	  const changed = Object.entries(draft).filter(([k, v]) => r?.targets.find((t) => t.target.key === k)?.pm_priority !== v);
207	  const canSubmit = !!choice && reasonOk(why) && !(choice === "approved" && blocked.length > 0);
208	
209	  const submit = useMutation({
210	    mutationFn: async () => {
211	      if (changed.length) await api.put(`/api/requirements/${item.req_id}/priorities`, { priorities: Object.fromEntries(changed), rationale: why });
212	      return api.post<{ priorities_set: string[] }>(`/api/requirements/${item.req_id}/status`, {
213	        status: choice,
214	        rationale: why,
215	        accept_ai_priorities: acceptAi && choice !== "rejected",
216	      });
217	    },
218	    onSuccess: (res) => {
219	      const n = changed.length + (res?.priorities_set?.length ?? 0);
220	      toast({
221	        tone: "ok",
222	        title: `${CHOICES.find((c) => c.v === choice)!.label}d · ${item.req_id}`,
223	        body: n ? `With ${n} market priorit${n === 1 ? "y" : "ies"} confirmed. Recorded in the audit trail.` : "Recorded in the audit trail.",
224	      });
225	      invalidateAll();
226	      onDone();
227	    },
228	    onError: (e: Error) => toast({ tone: "error", title: "Not recorded", body: e.message }),
229	  });
230	
231	  useEffect(() => {
232	    const k = (e: KeyboardEvent) => {
233	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
234	        if (canSubmit && !submit.isPending) submit.mutate();
235	        return;
236	      }
237	      if (isTyping(e) || e.metaKey || e.ctrlKey || e.altKey) return;
238	      const c = CHOICES.find((x) => x.key.toLowerCase() === e.key.toLowerCase());
239	      if (c) {
240	        e.preventDefault();
241	        setChoice(c.v);
242	        setTimeout(() => reasonRef.current?.querySelector("textarea")?.focus(), 0);
243	      }
244	    };
245	    window.addEventListener("keydown", k);
246	    return () => window.removeEventListener("keydown", k);
247	  });
248	
249	  if (q.isLoading) return <div className="panel ws-pad"><SkeletonBlock lines={10} /></div>;
250	  if (q.isError || !r) return <ErrorNote error={q.error} onRetry={() => q.refetch()} />;
251	
252	  return (
253	    <article className="ws">
254	      <header className="ws-head">
255	        <div className="row wrap" style={{ gap: 10 }}>
256	          <span className="id">{r.id}</span>
257	          <StatusLight s={r.status} />
258	          {item.is_new_in_wave && <span className="chip blue">New in this wave</span>}
259	          <Link to={`/requirements/${r.id}`} className="ws-open t-small">
260	            Full trace <ExternalLink size={13} />
261	          </Link>
262	        </div>
263	        <h2 className="ws-title">{r.title}</h2>
264	        <ReqTags r={r} />
265	      </header>
266	
267	      <div className="ws-grid">
268	        <div className="ws-main">
269	          <div className="panel ws-pad">
270	            <DecisionAsk r={r} />
271	          </div>
272	          <div className="panel ws-pad">
273	            <div className="sec-label">What customers say</div>
274	            <VoiceByMarket r={r} />
275	            <div style={{ height: 16 }} />
276	            <Quotes r={r} />
277	          </div>
278	          {(r.study.length > 0 || r.web.length > 0) && (
279	            <div className="panel ws-pad">
280	              <StudyAndWeb r={r} />
281	            </div>
282	          )}
283	          <Conflict r={r} />
284	          <div className="panel ws-pad">
285	            <AssumptionsBlock r={r} />
286	          </div>
287	        </div>
288	
289	        <div className="ws-side">
290	          <div className="panel">
291	            <div className="panel-head">
292	              <h3>Priority by car & market</h3>
293	              <span className="t-micro faint">Must ≥ 60 · Should ≥ 45</span>
294	            </div>
295	            <div className="ws-table">
296	              <MarketTable r={r} draft={draft} setDraft={setDraft} />
297	            </div>
298	          </div>
299	          <div className="panel ws-pad">
300	            <div className="sec-label">Fit checks</div>
301	            <FitGates fit={r.fit} overridden={r.overridden} onOverride={setOverride} />
302	          </div>
303	
304	          <div className="panel decision" ref={reasonRef}>
305	            <div className="decision-choices" role="radiogroup" aria-label="Decision">
306	              {CHOICES.map((c) => (
307	                <button key={c.v} role="radio" aria-checked={choice === c.v} className={`dchoice dc-${c.tone}`} onClick={() => setChoice(c.v)}>
308	                  <c.icon aria-hidden />
309	                  <span>{c.label}</span>
310	                  <Kbd>{c.key}</Kbd>
311	                </button>
312	              ))}
313	            </div>
314	            {choice === "approved" && blocked.length > 0 && (
315	              <p className="decision-block">Brand-fit fails for {blocked.map(targetLabel).join(", ")}. Override the gate above with a reason first.</p>
316	            )}
317	            <ReasonField id="dec-why" value={why} onChange={setWhy} placeholder={choice === "rejected" ? "Why this shouldn't go into the successor…" : "Why — evidence, trade-off, market…"} />
318	            {choice !== "rejected" && unset > 0 && (
319	              <label className="check">
320	                <input type="checkbox" checked={acceptAi} onChange={(e) => setAcceptAi(e.target.checked)} />
321	                <span>Also confirm the AI's priority for the {unset} market{unset === 1 ? "" : "s"} you haven't set</span>
322	              </label>
323	            )}
324	            <div className="row" style={{ justifyContent: "space-between" }}>
325	              <button className="btn btn-ghost" onClick={() => setAsk(true)}>
326	                <MessageCircleQuestion /> Ask the AI
327	              </button>
328	              <button className="btn btn-primary" disabled={!canSubmit || submit.isPending} onClick={() => submit.mutate()}>
329	                {submit.isPending ? "Recording…" : "Record decision"} <Kbd>⌘↵</Kbd>
330	              </button>
331	            </div>
332	          </div>
333	        </div>
334	      </div>
335	      <OverrideDrawer reqId={r.id} target={override} label={override ? targetLabel(override) : ""} onClose={() => setOverride(null)} />
336	      <ChallengeDrawer reqId={r.id} open={ask} onClose={() => setAsk(false)} />
337	    </article>
338	  );
339	}
