342	
343	function ProposalItem({ item, onDone, siblings }: { item: QueueItem; onDone: () => void; siblings: QueueItem[] }) {
344	  const all = useQuery({ queryKey: ["proposals", "open"], queryFn: () => api.get<Proposal[]>("/api/proposals?status=open") });
345	  const p = all.data?.find((x) => x.id === item.proposal_id || `prop:${x.id}` === item.uid);
346	  const toast = useToast();
347	  const [why, setWhy] = useState("");
348	  const [bulk, setBulk] = useState(false);
349	  const decide = useMutation({
350	    mutationFn: async (accept: boolean) => {
351	      if (bulk && siblings.length > 1) {
352	        const ids = siblings.map((s) => s.proposal_id ?? Number(s.uid.replace("prop:", "")));
353	        return api.post<{ done: number[]; failed: { id: number; detail: string }[] }>("/api/proposals/bulk-decision", { ids, accept, rationale: why });
354	      }
355	      return api.post(`/api/proposals/${p!.id}/decision`, { accept, rationale: why });
356	    },
357	    onSuccess: (_r, accept) => {
358	      toast({ tone: "ok", title: `${accept ? "Accepted" : "Rejected"}${bulk ? ` ${siblings.length} suggestions` : ""}`, body: "Recorded in the audit trail." });
359	      invalidateAll();
360	      onDone();
361	    },
362	    onError: (e: Error) => toast({ tone: "error", title: "Not recorded", body: e.message }),
363	  });
364	
365	  if (all.isLoading) return <div className="panel ws-pad"><SkeletonBlock lines={6} /></div>;
366	  if (!p) return <ErrorNote error={new Error("This suggestion is no longer open.")} onRetry={() => all.refetch()} />;
367	
368	  return (
369	    <article className="ws">
370	      <header className="ws-head">
371	        <div className="row wrap" style={{ gap: 10 }}>
372	          <span className="chip blue">
373	            <Sparkles /> AI suggests · {PROPOSAL_KIND[p.kind] ?? p.kind}
374	          </span>
375	          <span className="id">#{p.id}</span>
376	          {p.run && <span className="t-small faint">from run {p.run.id} · {fmtWhen(p.run.ts)}</span>}
377	          <Link to={`/requirements/${p.requirement_id}`} className="ws-open t-small">
378	            {p.requirement_id} <ExternalLink size={13} />
379	          </Link>
380	        </div>
381	        <h2 className="ws-title">{p.requirement_title}</h2>
382	      </header>
383	
384	      <div className="panel ws-pad prop-body">
385	        {p.kind === "priority" && (
386	          <div className="prop-priority">
387	            <div className="prop-target">{p.target?.label}</div>
388	            <div className="prop-change">
389	              <div className="col" style={{ gap: 6, alignItems: "center" }}>
390	                <span className="t-micro faint">Your priority</span>
391	                <PriorityMark p={(p.old_value as Priority) ?? null} />
392	              </div>
393	              <ArrowRight className="prop-arrow" aria-hidden />
394	              <div className="col" style={{ gap: 6, alignItems: "center" }}>
395	                <span className="t-micro faint">AI proposes</span>
396	                <PriorityMark p={(p.proposed_value as Priority) ?? null} ai />
397	              </div>
398	              {typeof p.delta?.score === "number" && (
399	                <div className="col" style={{ gap: 6, alignItems: "center", marginLeft: 18 }}>
400	                  <span className="t-micro faint">New score</span>
401	                  <ScoreBar score={p.delta.score as number} width={110} />
402	                </div>
403	              )}
404	            </div>
405	          </div>
406	        )}
407	        {p.kind === "extend" && <ExtendView p={p} />}
408	        {p.kind === "content" && (
409	          <div className="diff">
410	            <div className="sec-label">Field · {p.field.replace(/_/g, " ")}</div>
411	            <div className="diff-grid">
412	              <div className="diff-old">
413	                <div className="t-micro faint">Current</div>
414	                <p>{p.old_value || "—"}</p>
415	              </div>
416	              <div className="diff-new">
417	                <div className="t-micro" style={{ color: "var(--blue-ink)" }}>Proposed</div>
418	                <p>{p.proposed_value}</p>
419	              </div>
420	            </div>
421	          </div>
422	        )}
423	        {p.kind === "link_finding" && p.finding && (
424	          <div>
425	            <div className="sec-label">Link this finding as “{p.proposed_value}”</div>
426	            <div className="t-title" style={{ fontSize: 16 }}>{p.finding.title}</div>
427	            <p className="muted" style={{ marginTop: 6 }}>{p.finding.summary}</p>
428	          </div>
429	        )}
430	        {p.kind === "new_requirement" && <p className="t-lead">Accept to keep this new requirement in review; reject to drop it.</p>}
431	        {p.reason && (
432	          <div className="prop-cause">
433	            <div className="sec-label">Why the AI suggests this</div>
434	            <p>{p.reason}</p>
435	          </div>
436	        )}
437	      </div>
438	
439	      <div className="panel decision">
440	        <ReasonField id="prop-why" value={why} onChange={setWhy} placeholder="Why you accept or reject this suggestion…" />
441	        {siblings.length > 1 && (
442	          <label className="check">
443	            <input type="checkbox" checked={bulk} onChange={(e) => setBulk(e.target.checked)} />
444	            <span>Apply this answer to all {siblings.length} {PROPOSAL_KIND[p.kind]?.toLowerCase()}s in the queue</span>
445	          </label>
446	        )}
447	        <div className="row" style={{ justifyContent: "flex-end" }}>
448	          <button className="btn btn-danger" disabled={!reasonOk(why) || decide.isPending} onClick={() => decide.mutate(false)}>
449	            <X /> Reject
450	          </button>
451	          <button className="btn btn-primary" disabled={!reasonOk(why) || decide.isPending} onClick={() => decide.mutate(true)}>
452	            <Check /> Accept
453	          </button>
454	        </div>
455	      </div>
456	    </article>
457	  );
458	}
459	
460	function ExtendView({ p }: { p: Proposal }) {
461	  const d = (p.delta ?? {}) as { draft_title?: string; draft_description?: string; targets?: { vehicle_model_id: string; market_code: string; market_note?: string }[] };
462	  return (
463	    <div className="col" style={{ gap: 14 }}>
464	      <div className="extend">
465	        <div>
466	          <div className="t-micro faint">Raised again this wave as</div>
467	          <div className="extend-draft">“{d.draft_title}”</div>
468	          {d.draft_description && <p className="muted t-small" style={{ marginTop: 6 }}>{d.draft_description}</p>}
469	        </div>
470	        <GitMerge className="extend-icon" aria-hidden />
471	        <div>
472	          <div className="t-micro faint">Merge into existing</div>
473	          <div className="extend-draft">{p.requirement_title}</div>
474	        </div>
475	      </div>
476	      {d.targets && d.targets.length > 0 && (
477	        <div>
478	          <div className="sec-label">Adds car · market targets</div>
479	          <div className="row wrap" style={{ gap: 6 }}>
480	            {d.targets.map((t) => (
481	              <span key={t.vehicle_model_id + t.market_code} className="chip outline" title={t.market_note}>
482	                {targetLabel(`${t.vehicle_model_id}×${t.market_code}`)}
483	              </span>
484	            ))}
485	          </div>
486	        </div>
487	      )}
488	      {p.findings && p.findings.length > 0 && (
489	        <div>
490	          <div className="sec-label">Brings {p.findings.length} finding(s)</div>
491	          <ul className="sw-list">{p.findings.slice(0, 6).map((f) => <li key={f.id}>{f.title}</li>)}</ul>
492	        </div>
493	      )}
494	    </div>
495	  );
496	}
497	.decide { display: grid; grid-template-columns: 312px minmax(0, 1fr); gap: 22px; align-items: start; max-width: 1560px; }
