/* ---------------------------------------------------------------- what a wave does */

const FLOW: { who: "AI" | "System" | "You"; text: string }[] = [
  { who: "AI", text: "Reads the new evidence" },
  { who: "AI", text: "Drafts requirements, merges repeats" },
  { who: "AI", text: "Links evidence, re-checks fit" },
