function Flow() {
  return (
    <div className="tl-flow">
      <span className="tl-flow-h">Each wave</span>
      <ol>
        {FLOW.map((f, i) => (
          <li key={i}>
            <span className={`tl-who tl-who-${f.who.toLowerCase()}`}>{f.who}</span>
            <span>{f.text}</span>
            {i < FLOW.length - 1 && <ArrowRight aria-hidden className="tl-flow-arrow" />}
          </li>
        ))}
      </ol>
    </div>
  );
}

