// usage: node cdp.mjs <url> <out-prefix> <script.json>
// script: [{wait:ms}|{shot:name}|{eval:"js"}]
import { spawn } from "node:child_process";
import { writeFileSync, readFileSync, mkdtempSync } from "node:fs";
const [url, prefix, scriptPath] = process.argv.slice(2);
const steps = JSON.parse(readFileSync(scriptPath, "utf8"));
const dir = mkdtempSync("/private/tmp/claude-501/-Users-atahankilic-Documents-ehl-munich-final/c7f79221-413b-46d1-a535-ff2a11d3d1b2/scratchpad/chrome-");
const chrome = spawn("/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", [
  "--headless=new", "--remote-debugging-port=9333", `--user-data-dir=${dir}`, "--force-prefers-no-reduced-motion",
  "--disable-gpu-sandbox", "--use-angle=metal", "--enable-unsafe-swiftshader", "--hide-scrollbars", "--window-size=1440,900", "about:blank"], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let ws;
for (let i = 0; i < 50; i++) {
  try { const r = await fetch("http://127.0.0.1:9333/json"); const t = (await r.json()).find((x) => x.type === "page"); ws = new WebSocket(t.webSocketDebuggerUrl); break; } catch { await sleep(200); }
}
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const pending = new Map();
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } else if (m.method === "Runtime.consoleAPICalled" || m.method === "Runtime.exceptionThrown") console.log("[page]", JSON.stringify(m.params).slice(0, 400)); });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await send("Page.navigate", { url });
for (const s of steps) {
  if (s.wait) await sleep(s.wait);
  if (s.eval) { const r = await send("Runtime.evaluate", { expression: s.eval, awaitPromise: true, returnByValue: true }); console.log("eval:", JSON.stringify(r.result?.result?.value ?? r.result)); }
  if (s.shot) { const r = await send("Page.captureScreenshot", { format: "png" }); writeFileSync(`${prefix}-${s.shot}.png`, Buffer.from(r.result.data, "base64")); console.log("shot:", `${prefix}-${s.shot}.png`); }
}
ws.close(); chrome.kill();
process.exit(0);

